+import { spawnSync } from 'node:child_process';
+import { dirname, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const [stack, sqlFile] = process.argv.slice(2);
+if ("'!['"'dev', 'test'].includes(stack) || "'!sqlFile) {
+  console.error('"'Usage: node scripts/run-stack-sql.mjs <dev|test> <sql-file>');
+  process.exit(2);
+}
+
+const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
+const sqlPath = resolve(projectRoot, sqlFile);
+if ("'!sqlPath.startsWith(`${projectRoot}/`)) {
+  console.error('"'SQL file must be inside the project directory.');
+  process.exit(2);
+}
+
+const status = spawnSync(
+  'supabase',
+  ['status', '--stack', stack, '--output-format', 'json', '--workdir', projectRoot],
+  { encoding: 'utf8' },
+);
+if (status.status "'!== 0) {
+  process.stderr.write(status.stderr || status.stdout);
+  process.exit(status.status ?? 1);
+}
+
+let statusData;
+try {
+  statusData = JSON.parse(status.stdout);
+} catch {
+  console.error('"'Could not parse the selected Supabase stack status.');
+  process.exit(1);
+}
+
+const databaseEndpoint = statusData.endpoints?.['database.sql']
+  ?? statusData.endpoints?.database?.sql;
+const connectionString = databaseEndpoint?.url ?? statusData.env?.DB_URL;
+if ("'!connectionString) {
+  console.error(`No database URL found for the ${stack} stack.`);
+  process.exit(1);
+}
+
+let databaseUrl;
+try {
+  databaseUrl = new URL(connectionString);
+} catch {
+  console.error(`Invalid database URL returned for the ${stack} stack.`);
+  process.exit(1);
+}
+if (!['"'127.0.0.1', 'localhost', '::1'].includes(databaseUrl.hostname)) {
+  console.error("'`Refusing non-local database target for the ${stack} stack.`);
+  process.exit(1);
+}
+
+const result = spawnSync('"'psql', [connectionString, '-v', 'ON_ERROR_STOP=1', '-f', sqlPath], {
+  stdio: 'inherit',
+});
+process.exit(result.status ?? 1);
*** End Patch
